\section{Technical overview}
\label{sec:technical overview}

\paragraph{Regularity.} Quantum algorithms with low query weights will be at the heart of our analysis, and so it will be convenient for us to have the following terminology: 

    \begin{definition}[$\eta$-regularity]
    \label{def:regular}
    A quantum algorithm is {\sl $\eta$-regular} if its query weights $W_1(x),\ldots,W_N(x)$ satisfy
    \begin{equation*}
        \Ex_{\bx}[W_i(\bx)] \leq \eta \quad\quad\text{for all }i \in [N].
    \end{equation*}
\end{definition}

We will prove a ``regularity lemma" for this notion of regularity (\Cref{lem:regularity lemma}). We show that for any $t$-query quantum algorithm $\mcA$, there is a classical decision tree $T$ of depth $\poly(t,1/\eta,\log(1/\delta))$ such that $\mcA_\pi$ is $\eta$-regular for all but a $\delta$ fraction of its root-to-leaf paths $\pi$. This lemma is why the simulation conjecture follows from~\Cref{conj:our conjecture}: The latter, stated in the contrapositive, says that sufficiently regular quantum algorithms are well-approximated by constant functions, so $T$ itself serves as a good classical approximation of $\mcA$. 

\paragraph{\{$t$-query $d$-round\}  $\sse$ \{$t$-parallel $d$-round\}.} Instead of $t$-query $d$-round algorithms, all our results will hold for {\sl $t$-parallel} $d$-round algorithms. These algorithms can make $t$ parallel queries in {\sl each} round for $d$ rounds rather than $t$ queries in total (see~\Cref{def:RroundTparallelQalg}). Since our results concern the classical simulation of such algorithms, the same results also apply to $t$-query ones with the same parameters.

\subsection{Nonadaptive algorithms: The case of $d=1$}
\label{subsec:overview-nonadaptive}
\violet{To demonstrate the power of reasoning through query weights, we begin by showing that~\Cref{conj:our conjecture}, and therefore the simulation conjecture, has a one-page proof in the case of nonadaptive quantum query algorithms.}

\violet{Here and throughout the paper, for a function $f : \zo^N \to [0,1]$ we will be interested in the sets: 
\[ \Acc_f\coloneqq\{x:f(x)\geq 2/3\} \quad\text{and}\quad  \Rej_f\coloneqq\{x:f(x)\leq 1/3\}.
\]
When $f$ is clear from context, we simply write $\Acc$ and $\Rej$. The query weights $W_i(x)$ of nonadaptive algorithms do not depend on the input $x$, so we will just write $W_i$.
}

\begin{lemma}[\Cref{conj:our conjecture} is true for nonadaptive algorithms]
    \label{lem:nonadaptive-overview}
    Let $\mcA$ be a nonadaptive $t$-query quantum algorithm with query weights $W_1, \ldots, W_N$ and $f:\zo^N \to [0,1]$ denote its acceptance probability. There is some $i \in [N]$ for which
    \begin{equation*}
         W_i \ge \Omega\paren*{\frac{1}{t \ln(1/\delta)}} \quad\quad\text{ where }\delta \coloneqq \violet{\min\big\{{\Pr[\Acc_f]}, \Pr[\Rej_f]\big\}.}
    \end{equation*}
\end{lemma}
Our proof proceeds by contrapositive: We show that if $\linf{W}$ is sufficiently small \violet{(i.e.~if $\mcA$ is sufficiently regular)}, then one of $\Acc$ or $\Rej$ must be tiny. The only information about the function $f$ our proof uses is a rather simple consequence of \cite{BBBV97}'s hybrid method. For any two inputs $x,y \in \zo^N$, define the distance between them as,
\begin{equation*}
    \dist_W(x,y) \coloneqq \sum_{i \in \Delta(x,y)} W_i \quad\quad \text{where}\quad \Delta(x,y) \coloneqq \set{i \in [N]: x_i \neq y_i}.
\end{equation*}
The hybrid method shows that $\dist_W(x,y) \geq \Omega(1)$ for any $x \in \Acc$ and $y \in \Rej$. By the triangle inequality, this means every input $x \in \zo^N$ is far from at least one of these sets: 
\begin{equation*}
    \dist_W(x,\Acc) + \dist_W(x,\Rej) \geq \Omega(1) \quad\quad\text{where}\quad \dist_W(x,A) \coloneqq \min_{y \in A}\dist_W(x,y).
\end{equation*}
Consequently, the average input is far from one of these two sets: 
\begin{equation*}
    \max\bigg\{\Ex_{\bx}\bracket*{\dist_W(\bx,\Acc)}, \Ex_{\bx}\bracket*{\dist_W(\bx,\Rej)} \bigg\} \geq \lfrac{1}{2} \cdot \Omega(1) = \Omega(1).
\end{equation*}
At this point, we apply McDiarmid's bounded differences inequality~\cite{McD89,DP09}: For any set \violet{$A\sse \zo^N$} and inputs $x,x^{\oplus i}$ that differ in only the $i^{\text{th}}$ coordinate we have $\abs*{\dist_W(x, A) - \dist_W(x^{\oplus i},A)} \leq W_i$. Therefore,
\begin{equation*}
     \Prx_{\bx}\big[\dist_W(\bx,A) \le \E[\dist_W(\bx,A)] - \eps\big] \le  \exp\left(-\frac{2\eps^2}{\| W\|_2^2}\right) \leq \exp\left(-\frac{2\eps^2}{\lone{W}  \linf{W}}\right), 
\end{equation*}
where the first inequality is by McDiarmid's and the second is H\"older's. A $t$-query quantum algorithm has total query weight $\lone{W} \leq t$, and so we get that: 
\begin{align*}
    \min\set*{\Pr[\Acc],\Pr[\Rej]} &= \min\set*{\Prx_{\bx}[\dist_W(\bx,\Acc) = 0], \Prx_{\bx}[\dist_W(\bx,\Rej) = 0]} \\ &\leq \exp\left(-\Omega\paren*{\frac{1}{t\cdot  \linf{W}}}\right).
\end{align*}
Rearranging completes the proof of~\Cref{lem:nonadaptive-overview}. 

\subsection{Warm-up for $d \ge 2$: A doubly exponential bound}
\label{subsec:overview-warmup}
Extending these ideas to adaptive algorithms (i.e.~$d \ge 2$) requires overcoming a few challenges. We will first illustrate these ideas with a simpler proof that achieves quantitatively weaker parameters. This warm-up suffices to prove~\Cref{conj:our conjecture}, and therefore the simulation conjecture, when $d =O(1)$. However, its performance degrades quickly. For example, when $d = \violet{\polylog(t)}$, an important case corresponding to $\QNC$, it gives a bound that is exponential in $t$. 

\begin{lemma}[\violet{Parallel quantum algorithms have heavy variables; warm-up}] 
    \label{lem:warmup-overview}
    Let $\mcA$ be a $t$-parallel $d$-round quantum algorithm with query weights \violet{$W_1(x), \ldots, W_N(x)$} 
    and $f:\zo^N \to [0,1]$ denote its acceptance probability. There is some $i \in [N]$ for which
    \begin{equation*}
         \Ex_{\bx \sim \zo^N}[W_i(\bx)] \ge \paren*{dt \ln(1/\delta)}^{-\Omega(2^d)} \quad\quad\text{ where }\delta \coloneqq \violet{\min\big\{{\Pr[\Acc_f]}, \Pr[\Rej_f]\big\}}.
    \end{equation*}
\end{lemma}

\violet{We give a full proof of~\Cref{lem:warmup-overview} in~\Cref{sec:2^r} and describe the main ideas here.} We once again apply the hybrid method, but now need to be more careful. \violet{The obvious but key distinction is that when $d \ge 2$,} the queries may depend on the input. In this setting, the hybrid method gives
\[
    \dist_{W(x)}(x,y) \geq \Omega(1/d) \quad\quad\text{ for all } x\in \Acc\text{ and }y \in \Rej, \label{eq:basic hybrid}
\]
\violet{where crucially, the distance measure now depends on $x$. This introduces two difficulties.} The first is that our prior approach based on McDiarmid's inequality assumes a fixed vector $W$ satisfying that $\dist_W(x, A) - \dist_W(x^{\oplus i},A) \leq W_i$ for all inputs $x$. With this new input-dependent distance measure, we would instead want to bound $\dist_{W(x)}(x, A) - \dist_{W(x^{\oplus i})}(x^{\oplus i},A)$. The mismatch between the two distance measures makes this quantity more difficult to analyze.

\paragraph{Talagrand's convex-distance inequality.} To get around this first difficulty, we use a remarkable result due to Talagrand~\cite{Tal96}. \violet{The standard statement of this inequality is given in~\Cref{thm:Talagrand}; we use a straightforward corollary:}
\begin{corollary}[Easy consequence of Talagrand's convex-distance inequality; see~\Cref{cor:talagrand-linf}]
    \label{cor:Talagrand-overview}
    For any set $A \subseteq \zo^N$, vectors $\set{W(x)}_{x \in \zo^N}$ all satisfying \violet{$\lone{W(x)} \leq t$}, and thresholds $\eps,\gamma \geq 0$,
    \begin{equation*}
        \min\set*{\Pr[A],\Prx_{\bx}\bracket*{\dist_{W(\bx)}(\bx, A) \geq \eps }} \leq \exp\paren*{-\Omega\paren*{\lfrac{\eps^2}{t\gamma}}}+ \Prx_{\bx}[\linf{W(\bx)} \geq \gamma].
    \end{equation*}
\end{corollary}

\violet{In words,~\Cref{cor:Talagrand-overview} says that if $A$ is a large set and most $W(x)$'s have small $\| \cdot \|_\infty$, then most $x$'s are close to $A$, even if distance is measured in an $x$-specific manner according to $W(x)$.}
\violet{Note that the $d=1$ case is an immediate consequence of \Cref{cor:Talagrand-overview}}: In this case there is a single $W$ with $\linf{W} \le \eta$ and $\lone{W} \le t$, where for every $x \in \Acc$, we have $\dist_W(x,\Rej) \geq \Omega(1)$. Applying~\Cref{cor:Talagrand-overview} with $A = \Rej$ shows that either $\Acc$ or $\Rej$ must be tiny. The real power of~\Cref{cor:Talagrand-overview} comes in the setting of $d\ge 2$ where $W$ may now depend on $x$.

\violet{However, in order to apply~\Cref{cor:Talagrand-overview} we have to then overcome a second difficulty, that of bounding $\Pr[\| W(\bx)\|_\infty \ge \gamma]$ given only the assumption that every individual coordinate of $W(\bx)$ is small in expectation (i.e.~the assumption of $\eta$-regularity).} One could, of course, apply Markov's inequality on each individual coordinate $W_i(\bx)$. After a union bound over the $N$ coordinates, this gives
\begin{equation*}
     \Prx_{\bx}\bracket[\big]{\linf{W(\bx)} \gg  N  \eta} \ll 1.
\end{equation*}
\violet{Unfortunately, this is too lossy of an approach as it requires $\eta \ll 1/N$. The depth of the classical decision tree from our regularity lemma scales with $1/\eta$, and so this would result in a trivial bound.}   

\paragraph{Exponential tail bounds for query weights, proved inductively round-by-round.} Instead, we will show that $W_i(\bx)$ \violet{for any fixed $i\in [N]$} satisfies an exponential tail bound, \violet{which translates into only a logarithmic dependence on $N$ when we take a union bound}. Such a logarithmic dependence can then be removed using standard techniques \cite{DFKO07}. To obtain such a bound, we first break down the query weights into their individual \violet{round} contributions,
\begin{equation*}
    W_i(x) = w_i^{(1)} + w^{(2)}_i(x)+ \cdots + w^{(d)}_i(x).
\end{equation*}
\violet{We will bound $W_i(x)$ by bounding each $w_i^{(r)}(x)$.}
The first term $w_i^{(1)}$ does not depend on the input $x$ and is easy to handle. The key observation is that for any $r \geq 2$ and $i \in [N]$, the quantity $w^{(r)}_i(x)$ is itself the acceptance probability of an $(r-1)$-round algorithm. \violet{We can therefore use Talagrand's inequality to not only analyze the acceptance probabilities of quantum algorithms as sketched above, but also to analyze their query weights inductively:} 

\violet{
\begin{lemma}[Inductive step]
    \label{lem:query-weights-tail-overview} Consider any $t$-parallel $d$-round quantum algorithm. Fix $i\in [N]$ and $r\ge 2$ and suppose $\E_{\bx}[w_i^{(r)}(\bx)]\le \gamma_r$. Then for any $\gamma_{r-1}$, we have: 
    \begin{equation*}
        \Prx_{\bx}\big[w^{(r)}_i(\bx) \geq 4\gamma_r\big] \leq \Prx_{\bx}\bracket*{\max_{r' \le r-1}\set*{\linf{w^{(r')}(\bx)}} \geq \gamma_{r-1}} + \exp\paren*{-\Omega\paren*{\frac{\gamma_r^2}{\gamma_{r-1}r^4 t}}}.
    \end{equation*}
\end{lemma}
}

\violet{In words,~\Cref{lem:query-weights-tail-overview} reduces the task of controlling the round-$r$ query weights (LHS of above)  to that of controlling the round-$r'$ query weights for $r'\le r-1$ (RHS of above). Importantly, it translates an exponential tail bound on round-$r'$ weights into an exponential tail bound for round-$r$ weights, assuming only a bound on the expectation of round-$r$ weights.} 

To utilize \Cref{lem:query-weights-tail-overview}, we choose thresholds $\gamma_1 \le \cdots\le \gamma_d$ and define, for each round $r$: 
\begin{equation*}
    \Bad^{(r)} \coloneqq \set{x \in \zo^N: \linf{w^{(r)}(x)} > \gamma_r} \quad\quad\text{and} \quad\quad \Good \coloneqq \zo^N \setminus \bigcup_{r \in [d]} \Bad^{(r)}.
\end{equation*}
\Cref{lem:query-weights-tail-overview} allows us to conclude that $\Bad^{(r)}$ is small provided that:
\begin{enumerate}
    \item The choice of thresholds satisfies $\gamma_{r-1} \ll \gamma_r^2$, \violet{chosen so that the second term on the RHS of~\Cref{lem:query-weights-tail-overview} is sufficiently small.} 
    \item The prior sets $\Bad^{(1)}, \ldots, \Bad^{(r-1)}$ are all sufficiently small.
    \item The query weights are sufficiently small in expectation, \violet{which is implied by our regularity assumption. (As in the nonadaptive case, our proof of~\Cref{lem:warmup-overview} proceeds via the contrapositive, showing that sufficiently regular algorithms must be biased.)} 
\end{enumerate}
We set the parameters in such a way that all these conditions are satisfied for all rounds $r$, meaning that most $x's$ are in $\Good$. \violet{This yields a bound on $\Prx\big[\| W(\bx)\|_\infty\ge \gamma\big]$, which allows us to apply Talagrand's inequality yet again to prove \Cref{lem:warmup-overview}.} 

The requirement that $\gamma_{r-1} \ll \gamma_r^2$ is why \Cref{lem:warmup-overview} has a doubly exponential dependence on~$d$: Chaining this inequality for all $r \in [d]$ gives that $\gamma_1 \ll (\gamma_d)^{2^{d}}$.  \violet{We then have to set the regularity parameter~$\eta$ to be correspondingly small for the base case of our inductive proof to go through. }

\subsection{An improved bound for $d \ge 2$ via higher-order statistics}
\label{subsec:overview-improved}
Using a few additional ideas and a much more careful analysis we are able to prove the following.
\begin{theorem}[\violet{Parallel quantum algorithms have heavy variables}; improved bound]
    \label{thm:rsquared-overview}
    Let $\mcA$ be a $t$-parallel $d$-round quantum algorithm with query weights \violet{$W_1(x), \ldots, W_N(x)$} and $f:\zo^N \to [0,1]$ denote its acceptance probability. There is some $i \in [N]$ for which
    \begin{equation*}
         \Ex_{\bx \sim \zo^N}[W_i(\bx)] \ge 2^{-\Omega(d^2)} \cdot (t\log(1/\delta))^{-\Omega(d)} 
         \quad\quad\text{ where }\delta \coloneqq \violet{\min\big\{{\Pr[\Acc_f]}, \Pr[\Rej_f]\big\}}.
    \end{equation*}
\end{theorem}
Our proof of \Cref{thm:rsquared-overview} will be based on more fine-grained information about the quantum algorithm than in \Cref{lem:warmup-overview}. Rather than just  analyzing the query weights of \textsl{individual coordinates}, we will analyze the query weights of \textsl{sets}. On an input $x\in \zo^N$, each round $r\in [d]$ of a $t$-parallel algorithm induces a distribution $\mcD_x^{(r)}$ over subsets of $[N]$ of size at most $t$.  
These distributions encode more information than the query weights of coordinates, as the latter can be easily recovered using the simple equality,
\begin{equation*}
    w_i^{(r)}(x) = \Prx_{\bS \sim \mcD_x^{(r)}}[i \in \bS].
\end{equation*}
We can now describe the main differences between the proofs of \Cref{thm:rsquared-overview} and \Cref{lem:warmup-overview}.

\paragraph{$\Good$ vs $\Bad$.}  \violet{The proof of~\Cref{lem:warmup-overview} is based on a partition of inputs into $\Bad^{(r)}$ and $\Good^{(r)}\coloneqq \zo^N\setminus \Bad^{(r)}$, where the definitions of these sets are chosen to facilitate applications of Talagrand's inequality to the inputs in $\Good^{(r)}$. Specifically, we consider an input $x$ good if $\| w^{(r)}(x) \|_\infty \le \gamma_r$. This can be interpreted as saying that $\mathcal{D}_x^{(r)}$ is ``well-spread" in the sense that 
\[ \Prx_{\bS \sim \mathcal{D}_x^{(r)}}[i\in \bS]\le \gamma_r \quad \text{for all $i\in [N]$}.  \]
This notion of goodness is therefore based on ``singleton statistics" (i.e.~``$1$-wise statistics") of $\mathcal{D}_x^{(r)}$. }

Goodness in the proof of~\Cref{thm:rsquared-overview} will instead be based on a broader set of $m$-wise statistics of $\mathcal{D}_x^{(r)}$ where $m\ge 1$. We now consider an input $x$ good if $\mathcal{D}_x^{(r)}$ is well-spread in the sense that 
\begin{equation} \Prx_{\bS\sim \mathcal{D}_x^{(r)}}[\bS\cap T \ne\emptyset] \le \gamma_r \text{ for all subsets $T\sse [N]$ of size $m_r$.}\label{eq:well spread overview}
\end{equation}

\violet{We say that $\mcD_x^{(r)}$ is {\sl $(m_r,\gamma_r)$-spread} if it satisfies the above, and {\sl $(m_r,\gamma_r)$-hit} otherwise.}

\violet{Recall that the bottleneck in our proof of~\Cref{lem:warmup-overview} was the recurrence relationship $\gamma_{r-1}\ll \gamma_r^2$, which resulted in $\gamma_1$ being doubly exponential in $d$. With this new dual-parameter notion of spreadness, with an appropriately large choice of $m_r$ our recurrence relationship becomes $\gamma_{r-1}\le c\gamma_r$ for some absolute constant $c$, which results in $\gamma_1$ only being singly exponentially in $d$. 

}

\paragraph{Stronger distance guarantees via a more careful hybrid method.} \violet{Note, however, that $(m_r,\gamma_r)$-spreadness becomes a stricter guarantee the larger $m_r$ is. Since the size of $\Good^{(r)}$ shrinks as $m_r$ becomes large, it is more challenging to bound the size of $\Bad^{(r)}$ when we work with this new notion. 

We overcome this in two ways. We first show that the hybrid method actually gives a stronger guarantee than what we used in the proof of~\Cref{lem:warmup-overview}. Our proof of~\Cref{lem:warmup-overview} uses the fact that if $x\in \Acc$ and $y\in \Rej$, then} 
\violet{
\begin{equation*}
    \sum_{r \in [d]} \dist_{w^{(r)}(x)}(x,y) \geq \Omega(1/d) \quad\text{where} \quad \dist_{w^{(r)}(x)}(x,y) \coloneqq \sum_{i\in \Delta(x,y)} w^{(r)}_i(x). 
\end{equation*}
Working directly with the distributions $\mcD_x^{(r)}$, the hybrid method gives the stronger bound: 
\begin{equation}
    \sum_{r \in [d]} \dist_{\mcD_x^{(r)}}(x,y) \geq \Omega(1/d) \quad\text{where} \quad \dist_{\mathcal{D}_x^{(r)}}(x,y) \coloneqq \Prx_{\bS\sim\mathcal{D}_x^{(r)}}[x_{\bS} \ne y_{\bS}]. \label{eq:new distance overview} 
\end{equation}
This bound is indeed stronger since 
\begin{align*}
\Prx_{\bS\sim\mcD_x^{(r)}}[x_{\bS}\ne y_{\bS}] &= \Prx_{\bS\sim\mathcal{D}_x^{(r)}}[\bS \cap \Delta(x,y)\ne \emptyset] \\
&\le \Ex_{\bS \sim \mathcal{D}_x^{(r)}}[|\bS \cap \Delta(x,y)|]\ =\ \sum_{i\in \Delta(x,y)} \Prx_{\bS\sim\mathcal{D}_x^{(r)}}[i\in \bS] \ = \ \sum_{i\in \Delta(x,y)} w_i^{(r)}(x).  
\end{align*} }

\paragraph{Our main concentration inequality.} \violet{Next, we prove a generalization of~\Cref{cor:Talagrand-overview}, the reformulation of Talagrand's inequality that we used repeatedly in the proof of~\Cref{lem:warmup-overview}. This version incorporates our new notions of well-spreadness (\ref{eq:well spread overview}) and distance (\ref{eq:new distance overview}):}

\begin{lemma}[Well-spread distributions cannot separate large sets; see~\Cref{lem:dist-to-hit}]
    \label{lem:dist-to-hit-overview}
   For any set $A \subseteq \zo^N$, distributions  $\set{\mcD_x}_{x \in \zo^N}$ supported on subsets of $[N]$ of size at most $t$, and thresholds $\eps,\gamma \geq 0$,
        \begin{equation*}
        \min\set*{\Pr[A], \Prx_{\bx}\big[ \dist_{\mcD_{\bx}}(\bx, A) \geq \eps\big] }\leq \exp\paren*{-\Omega\paren*{\frac{(\eps-\gamma)^2m}{\gamma t}}} + \Prx_{\bx}\big[\mcD_{\bx}\text{ is }(m,\gamma)\text{-hit}\,\big].
    \end{equation*} 
\end{lemma}
\violet{\Cref{lem:dist-to-hit-overview} recovers~\Cref{cor:Talagrand-overview} when $m=1$. We note the tension between the two terms on the RHS: As $m$ grows, the first becomes smaller whereas the second becomes larger.} 

\violet{With~\Cref{lem:dist-to-hit-overview} in hand, our proof of~\Cref{thm:rsquared-overview} shares the same overall structure as that of~\Cref{lem:warmup-overview}. For each round $r\in [d]$, we consider a set of bad inputs $\Bad^{(r)} \sse \zo^N$, now defined as those whose distributions $\mathcal{D}^{(r)}_x$ are $(m_r,\gamma_r)$-hit. We argue inductively, using~\Cref{lem:dist-to-hit-overview}, that if $\Bad^{(1)},\ldots,\Bad^{(r-1)}$ are small then $\Bad^{(r)}$ is small as well. Having shown that most inputs fall in $\Good \coloneqq \zo^N \setminus \bigcup_r \Bad^{(r)}$, we then apply~\Cref{lem:dist-to-hit-overview} once more to conclude that $\Pr[\Acc]\cdot \Pr[\Rej\cap\Good]$ is small. 

}

\subsection{Implications for random-oracle separations: Proofs of~\Cref{thm:random oracle unrelativized equivalence,thm:QNC equivalence}}

\label{sec:implications for random oracle separations technical overview}


\violet{Separations in the query model yield relativized separations, but the converse does not necessarily hold: simulations in the query model do not necessarily yield relativized simulations. In particular, the simulation conjecture alone does not imply that $\mathsf{BPP}^{\bmcO} =  \mathsf{BQP}^{\bmcO}$ for a random oracle $\bmcO$. While it guarantees that every quantum Turing machine making $\poly(n)$ queries to an oracle has an approximator that only makes $\poly(n)$ classical queries, it does not guarantee that this approximator can be implemented using only $\poly(n)$ classical {\sl time steps}. 

To prove~\Cref{thm:random oracle unrelativized equivalence}, we show that the specific approximators that we construct via~\Cref{conj:our conjecture} do admit time-efficient implementations assuming $\PromiseBPP= \PromiseBQP$. To sketch why, first recall that~\Cref{conj:our conjecture} implies the simulation conjecture via a regularity lemma, which we now state formally:}
\begin{restatable}[Regularity lemma]{lemma}{regularityoverview}
\label{lem:regularity lemma}
Let $\mcA$ be a $t$-query quantum algorithm. There is a classical
decision tree $T$ of depth $\poly(t,1/\eta,\log(1/\delta))$ such that
the restricted algorithm $\mcA_{\bpi}$ is $\eta$-regular  with probability at least 
$1-\delta$ with respect to a random root-to-leaf path $\bpi\sim T$ induced by a uniform random input $\bx\sim \zo^N$.
\end{restatable}

\violet{This tree $T$ is constructed using a simple greedy algorithm: If $\mcA$ is already $\eta$-regular, we are done. Otherwise, there must be at least one variable $i\in [N]$ with query weight larger than $\eta$. We query any such variable at the root of our decision tree and recurse on $\mcA_{x_i=0}$ and $\mcA_{x_i=1}$. We use a martingale argument to show that a random path through this tree will w.h.p.~terminate after not too many steps, and~\Cref{lem:regularity lemma} follows.}

\violet{For our proof of~\Cref{thm:random oracle unrelativized equivalence}, we further need an algorithmic version of this regularity lemma:}

\begin{lemma}[Algorithmic regularity lemma, see \Cref{cor:algorithmic_regularity_lemma} for the formal version]
\label{lem:algorithmic regularity lemma overview}
\violet{If $\PromiseBPP = \PromiseBQP$, there is an efficient randomized algorithm that takes as input a representation of $\mcA$ as a quantum oracle circuit and on any input $\mcO\in\zo^N$ computes that path $\pi$ in $T$ that $\mcO$ follows.
}
\end{lemma}

\violet{A natural attempt at proving~\Cref{lem:algorithmic regularity lemma overview} would be to estimate the query weight of each variable $i\in [N]$, in search of one with weight at least $\eta$. This would be the root node in the path~$\pi$, and we can then recurse. However, such a search is too time consuming: A $\BQP$ oracle algorithm makes at most $\poly(n) = \polylog(N)$ queries to $\mcO\in \zo^N$, and so our classical simulation has to take at most $\polylog(N)$ classical time steps. We instead give a $\PromiseBQP$ algorithm for estimating {\sl sums} of query weights, $\sum_{i \in S} \Ex_{\bx}[W_i(\bx)]$ for any subset $S\sse [N]$.  With this subroutine in hand, a standard branch-and-prune algorithm (\'a la~\cite{GL89,KM93}) allows us to identify a variable of high query weight with only a logarithmic dependence on $N$. 

\Cref{thm:random oracle unrelativized equivalence} then follows easily, 
and the proof of~\Cref{thm:QNC equivalence} is completely analogous.   
}

\violet{\paragraph{Complexity of finding high query weight vs.~high influence variables.} \cite{AA14}'s reduction of the simulation conjecture to their conjecture is also based on a regularity lemma,  where their notion of a regular quantum algorithm is one whose {\sl influences}, rather than query weights, are all low. They also showed that their regularity lemma can be made algorithmic, but under the much stronger assumption that $\mathsf{P} = \mathsf{P}^{\#\mathsf{P}}$ rather than $\mathsf{PromiseBPP} = \mathsf{PromiseBQP}$. The crux of this difference lies in the fact that our subroutine for finding a variable of high query weight,
as discussed above, is in $\PromiseBQP$, whereas~\cite{AA14}'s subroutine for finding one of high influence is in $\mathsf{NP}^{\#\mathsf{P}}$. 

This highlights a dual advantage of query weights over influences. On one hand, since query weights upper bound influences (after suitable normalization, see~\Cref{prop:query-weight-to-inf}), any regularity lemma for low query weights also serves as one for low influences. And yet, somewhat paradoxically, our regularity lemma for query weights admits a much more efficient algorithmic implementation than~\cite{AA14}'s one for influences. 

}

