\section{Sample Complexity and Statistical Proofs}\label{sec:ub-proof}
\subsection{Pauli Work Investment Lemma} 
We will prove that there exists a Levin's Work Investment style strategy for Pauli basis measurements.
\begin{proof}[Proof of~\cref{lem:pauli_work_invest}]
Before we proceed, we will first re-prove a classical Levin's Work Investment lemma.
\begin{lemma}[Levin's Work Investment Strategy]\label{lem:work_invest}
    Let $X \sim \unif[k]$. If $\expectDistrOf{}{f(X)} \geq \mu$ and $f(X)\geq 0$. Then, there exists $i \in [\lceil \log_3 k\rceil]$ such that,
    \begin{align*}
        \Pr[f(X) \geq 3^{i-2} \mu] \geq \frac{3^{-i}}{\lceil \log_3 k \rceil},
    \end{align*}
\end{lemma}
\begin{proof}
Let $M=\lceil \log_3 k \rceil$.
    We proceed by contradiction. Assume $\Pr[f(X) \geq 3^{i-2} \mu] < \frac{3^{-i}}{M}$ for all $i \in [M]$. We observe that $\Pr[f(X) \geq k \mu/3] = 0$ since any element on the support of $f(X)$ should have probability $\geq 1/k$. Thus, we can split the expectation up into a finite number of bins $B_j = \{x: 3^j  \mu \leq f(x) \leq 3^{j+1} \mu\}$.
    \begin{align*}
        \expectDistrOf{}{f(X)} &\leq \frac{\mu}{3} +  \sum_{j=1}^{M-1} \Pr[f(X) \in B_j] \cdot 3^{j+1} \mu \\
                            &< \frac{\mu}{3} + \frac{\mu}{3} \sum_{j=1}^{\log_3 k} \frac{1}{M} \leq \frac{\mu}{3} + \frac{\mu}{3} < \mu
    \end{align*}
    We have reached a contradiction.
\end{proof}
\noindent We can now show \cref{lem:pauli_work_invest} as a direct consequence of \cref{lem:work_invest}.
    We look at the expectation of $L_P$,
    \begin{align*}
    \expectDistrOf{}{L_P} &= \frac{1}{3^N} \sum_{P \in \{X,Y,Z\}^{\otimes N}} \sum_{Q \triangleleft P} 3^{w(Q)} \alpha_Q^2 \\
    &= \frac{1}{3^N} \sum_{Q \in \mathcal{Q}} \alpha_Q^2 \cdot 3^{N-w(Q)} \cdot 3^{w(Q)} = L.
    \end{align*}
    The statement is proven by applying \cref{lem:work_invest}.
\end{proof}
\subsection{Correlation-Concentrated Testing}
We will prove the correctness of the \verb|KrawtCheck| subroutine, giving us a polynomial-time uniformity tester of correlation-sparse distributions.
\begin{proof}[Proof of~\cref{thm:sparse-test}]
    It is clear that \cref{alg:sparse} uses $\mathcal{O}(Mn) = \bigO{\frac{\sqrt{\binom{N}{k}}}{\beta\Delta} \ln \frac{1}{\delta}}$ samples. 

    \noindent We will show that $W_k$ is an unbiased statistic for $\|\alpha^{=k}\|_2^2$ by making use of the observation from~\cref{eq:k-sym}
    \begin{align*}
    f(x) = \sum_{|S| = k} \parity{x} = K_k^{(N)}(w_{H}(x)).
    \end{align*}
    Coupled with the fact that $d_{H}(x,y) = w_H(x \oplus y)$,
    \begin{align*}
        \expectDistrOf{}{W_k} &= \expectDistrOf{X,Y \sim p}{\krawt{k}{w_{H}(X \oplus Y)}} = \sum_{x} p(x) \sum_{y} p(y) f(x \oplus y)\\
        &= 2^N \sum_{x} p(x) (p*f)(x) = 4^N \dotprodB{p}{p*f}.
    \end{align*}
    By the convolution property of Boolean functions, $p*f (x) = \frac{1}{2^N} \sum_{|S|=k} \parity{x} \alpha(S)$. By Parseval's Theorem, the inner product $\dotprod{p}{p*f}_B$ is the inner product of their Fourier expansions, resulting in $\frac{1}{4^N} \|\alpha^{=k}\|_2^2$. 

    We have shown that $W_k$ is an unbiased statistic of $\|\alpha^{=k}\|_2^2$, which is $0$ when $p=u$ and $\geq \beta\Delta$ when $p \in \mathcal{P}$. Thus, it suffices to estimate $W_k$ with accuracy $\kappa_1 \cdot \beta \Delta$ when $p=u$ and $\kappa_2 \cdot \|\alpha^{=k}\|_2^2$ when $p \in \mathcal{P}$ to distinguish between the two classes. We proceed to bound the variance of $W_k$ to show that the error is well-controlled for detection,
    \begin{align*}
        \Var(W_k) &= \frac{1}{n^4} \expectDistrOf{}{\left(\sum_{i=1}^n \sum_{j=1}^n \krawt{k}{d_{H}(X_i,Y_i)}\right)^2} - \|\alpha^{=k}\|_2^4.
    \end{align*}
    When we expand the second moment, we will look at correlations between pairs $(X,Y), (X',Y')$. We will split the correlations into three cases: (1) when the pairs are disjoint, (2) when the pairs share one element, and (3) when the pairs are the same. 
    \begin{align*}
    \expectDistrOf{}{\left(\sum_{i=1}^n \sum_{j=1}^n \krawt{k}{d_{H}(X_i,Y_i)}\right)^2} =\; &n^2(n-1)^2 \|\alpha^{=k}\|_2^4 + 2n^3 \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}\krawt{k}{d_{H}(X,Y')}} \\
    &+ n^2 \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}^2}.
    \end{align*}
    The first case is simple as the two variables will be independent. Consider the expectation when the pairs of samples share exactly one element,
    \begin{align*}
        \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}\krawt{k}{d_{H}(X,Y')}} &= \sum_{x} p(x) \left(\sum_{y} p(y) \krawt{k}{w_{H}(x\oplus y)}\right)^2 \\
        &= 8^N \dotprodB{p}{(p*f)^2}
    \end{align*}
    We make the observation that 
    \begin{align*}
    (p*f)^2(x) = \frac{1}{4^N} \sum_{|S_1|=|S_2|=k} \alpha(S_1) \alpha(S_2) \cdot \chi_{S_1 \Delta S_2}(x). 
    \end{align*}
    Define a new set of coefficients that includes the empty set: $\tilde{\alpha}(S) = \alpha(S)$ and $\tilde{\alpha}(\emptyset) = 1$. Applying Parseval's Theorem,
    \begin{align*}
        \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}\krawt{k}{d_{H}(X,Y')}} = \sum_{|S_1|=|S_2|=k} \tilde{\alpha}(S_1 \Delta S_2) \alpha(S_1) \alpha(S_2).
    \end{align*}
    For convenience, we define the quantity 
    \begin{align*}
    g(k) \eqdef \begin{cases}
        2k & \text{if }  k \leq \nqubits/2 \\
        2(\nqubits-k) &  \text{otherwise}.
    \end{cases}
    \end{align*}
    We can now complete the bound with Cauchy-Schwarz inequality,
    \begin{align*}
        \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}\krawt{k}{d_{H}(X,Y')}} &\leq \sqrt{\sum_{|S_1|=|S_2|=k} \tilde{\alpha}(S_1 \Delta S_2)^2} \cdot \sqrt{\sum_{|S_1|=|S_2|=k} \alpha(S_1)^2 \alpha(S_2)^2} \\
        &\leq \sqrt{\sum_{\substack{|S| \leq g(k) \\ |S| \text{ even}}} 2 \binom{|S|}{|S|/2} \binom{N-|S|}{k-|S|/2} \cdot \tilde{\alpha}(S)^2}  \cdot \|\alpha^{=k}\|_2^2 \\
        &\leq \sqrt{ 2 \binom{N}{k}} \|\alpha\|_2 \|\alpha^{=k}\|_2^2 + \sqrt{2 \binom{N}{k}} \|\alpha^{=k}\|_2^2 \\
        &\leq \sqrt{2 \beta^{-1} \binom{N}{k}} \|\alpha^{=k}\|_2^3 + \sqrt{2 \binom{N}{k}} \|\alpha^{=k}\|_2^2,
    \end{align*}
    where we used the fact that $\sqrt{a+b} \leq \sqrt{a} + \sqrt{b}$ and the assumption $\|\alpha^{=k}\|_2^2 \geq \beta\|\alpha\|_2^2$ when $p \in \mathcal{P}^{(\Delta, k ,\beta)}$. Now, we shift our attention to bounding the second moment,
    \begin{align*}
        \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}^2} &= \sum_{x} p(x) \sum_{y} p(y) \krawt{k}{w_{H}(x \oplus y)}^2 \\
        &= 4^N \dotprodB{p}{p * f^2}.
    \end{align*}
    We make an observation regarding the convolution $p*f^2$.
    \begin{align*}
    f^2(x) &= \sum_{|S_1|=|S_2|=k} \chi_{S_1 \Delta S_2}(x) = 2 \sum_{\substack{1 \leq |S| \leq g(k) \\ |S | \text{ even}}} \binom{|S|}{|S|/2} \binom{N-|S|}{k-|S|/2} \chi_{S}(x) + \binom{N}{k} \chi_{\emptyset}(x) \\ 
    p*f^2(x) &= \frac{2}{2^N} \sum_{\substack{|S| \leq g(k) \\ |S | \text{ even}}} \binom{|S|}{|S|/2}  \binom{N-|S|}{k-|S|/2} \alpha(S) \cdot \chi_{S}(x) + \frac{\binom{N}{k}}{2^N}
    \end{align*}
    We can apply Parseval's Theorem once more to obtain the following second moment bound,
    \begin{align*}
        \expectDistrOf{}{\krawt{k}{d_{H}(X,Y)}^2} &= 2 \sum_{\substack{|S| \leq 2k \\ |S | \text{ even}}} \binom{|S|}{|S|/2} \binom{N-|S|}{k-|S|/2} \alpha(S)^2 + \binom{N}{k} \\
        &\leq 2 \binom{N}{k} \|\alpha\|_2^2 + 2 \binom{N}{k} \leq 2\beta^{-1}\binom{N}{k} \|\alpha^{=k}\|_2^2 + 2 \binom{N}{k}.
    \end{align*}
    Thus, 
    \begin{align*}
        \Var(W_k) &\leq \frac{ 2\sqrt{ 2 \binom{N}{k}} \|\alpha^{=k}\|_2^3}{\sqrt{\beta} n} + \frac{2\sqrt{2 \binom{N}{k}} \|\alpha^{=k}\|_2^2}{n} +\frac{2 \binom{N}{k} \|\alpha^{=k}\|_2^2}{\beta n^2} + \frac{2 \binom{N}{k}}{n^2}.
    \end{align*}
    With $n = \frac{400\sqrt{2 \binom{N}{k}}}{\beta \Delta}$, the variance under $p \in \mathcal{P}$ will be
    \begin{align*}
        \Var(W_k) \leq \frac{\sqrt{\beta \Delta} \|\alpha^{=k}\|_2^3}{200}  + \frac{\beta \Delta \|\alpha^{=k}\|_2^2}{200} + \frac{\beta \Delta \|\alpha^{=k}\|_2^2}{40000} + \frac{\beta^2 \Delta^2}{40000} \leq \frac{\|\alpha^{=k}\|_2^4}{49}.
    \end{align*}
    Since $\|\alpha^{=k}\| = 0$ when $p=u$, the variance under the null hypothesis will be
    \begin{align*}
    \Var(W_k) &\leq\frac{2\binom{N}{k}}{n^2} \leq \frac{\beta^2 \Delta^2}{40000}. 
    \end{align*}
    By Chebyshev's inequality,
    \begin{align*}
        \Pr_{p \in \mathcal{P}}\left[W_k \geq \frac{\|\alpha^{=k}\|_2^2}{50} \geq \frac{\beta \Delta}{50}\right] \geq \frac{3}{4}, \quad \Pr_{p=u}\left[W_k < \frac{\beta \Delta}{50}\right] \geq \frac{3}{4}.
    \end{align*}

    By symmetry of the error probabilities, it suffices to look at the error of the final statistic under the alternative hypothesis WLOG. When $p \in \mathcal{P}$, $\sum_{i=1}^M T_i \sim Bin(\gamma, M)$, where $\gamma \geq \frac{3}{4}$. By Chernoff's bound,
    \begin{align*}
    \Pr\left[\sum_{i=1}^M T_i \leq \frac{M}{2}\right] \leq e^{-\frac{M}{16}} = \delta,
    \end{align*}
    Thus, we have proved the correctness of~\cref{alg:sparse}.
    \end{proof}
    \section{Computational Efficiency of\texorpdfstring{~\cref{alg:sparse}}{Algorithm 2}}
    We now prove that correlation-concentrated uniformity testing can be done in $poly(n,\nqubits,k)$ time.
    \begin{proof}[Proof of~\cref{cor:eff-sparse}]
    An important observation is that the Krawtchouk polynomials can be generated through a 3-term recurrence~\cite[Chapter 9.11]{koekoek2010hypergeometric},
    \begin{align*}
        \krawt{k}{t} = \frac{2N - 3k -t}{2(n-k)} \krawt{k-1}{t} + \frac{k}{2(n-k)} \krawt{k-2}{t}.
    \end{align*}    
    Since there is a constant number of additions, divisions and multiplications of integers in $[-2^N, 2^N]$, each recurrence can be computed in time $\bigO{\nqubits \log \nqubits}$ using standard fast multiplication algorithms~\cite{harvey2021integer}, as division can be reduced to multiplication via Newton-Raphson method. Therefore, iteratively computing $\krawt{k}{t}$ can be done in $\bigO{k\nqubits \log \nqubits}$ time with standard dynamic programming methods. Coupled with the additional $\bigO{n^2 \cdot \nqubits}$ time for computing the Hamming distance between samples and summing over $n^2$ integers of magnitude $2^\nqubits$, we have an algorithm that runs in $\bigO{n^2 \cdot k\nqubits \log \nqubits + 2 n^2 \cdot \nqubits} = \bigO{n^2 \cdot k\nqubits \log \nqubits}$ time, yielding an exponential improvement over the naïve parity-enumeration algorithm.
    \end{proof}

