\section{The Lower bound} \label{sec:gen-bound}
The key idea behind our nearly-optimal lower bound is to derive bounds that depend on the measurement constraints. This allows us to obtain tighter guarantees under restricted measurement settings. Recall, the goal is to design a measurement scheme $\POVM^n= \POVM^{(1)} \otimes \POVM^{(2)} \otimes \ldots \otimes \POVM^{(\nsamp)}$ such that 
\begin{align} \label{def:cert-goal}
    \Pr_\qmm[T(x^n) = \mathtt{Maximally-Mixed}] \geq \frac{2}{3}, \quad
    \min_{\sigma: \tracenorm{\sigma-\qmm} \geq \eps}\Pr_{\sigma}[T(x^n) = \mathtt{Not \; Maximally-Mixed}] \geq \frac{2}{3},
\end{align}
where $x^n$ are the outcomes of the adaptive measurement scheme $\POVM^{(i)} = g_i(x^{i-1})$ for some randomized function $g_i: \mathcal{X}^{i-1} \rightarrow \povmset$. For single copy measurements, it suffices to consider the conditional distributions of the measurement outcomes $x_i | x^{i-1}$.

\subsection{Our Measurement-dependent Framework}
To establish the lower bound, we will be using the ``tried and true'' Lecam's two point method. Consider an ensemble of states $\mathcal{P} \subset \{\sigma: \tracenorm{\sigma -\qmm } \geq \eps\}$ where each state is drawn according to distribution $\nu$. 

In classical identity testing, Lecam's method states that a valid tester must be able to distinguish between the mixture of the ensemble of perturbed distributions and the null hypothesis~\cite{Paninski08}. Similarly, a valid quantum certification protocol must be able to distinguish $\qmm$ from $\expectDistrOf{\rho \sim \nu}{\rho}$.
\begin{lemma}[{\cite[Lemma 3.3]{Liu2024role}}]
Suppose nature selects $\rho = \qmm$ with probability $1/2$ and draws from the ensemble $\rho \sim \nu$ with probability $1/2$. Then, a measurement scheme that performs mixedness testing must satisfy
\begin{align} \label{eq:lecam}
        \frac{1}{2}\le \kldiv{\q^{\out^\ns}}{\p^{\out^\ns}}=\sum_{i=0}^{\ns-1}\expectDistrOf{\q^{\out^\ns}}{\kldiv{\q^{\out_{i+1}|\out^{i}}}{\p^{\out_{i+1}|\out^{i}}}},
\end{align}
where $\q^{\out^\nsamp}(x^n) = \expectDistrOf{\sigma \sim \nu}{\Pr[\forall_{i \in [\nsamp]} \; \POVM^{(i)}(\sigma) = x_i]}$ and $\p^{\out^\nsamp}(x^n) = \Pr[\forall_{i \in [\nsamp]} \; \POVM^{(i)}(\qmm) = x_i]$. The corresponding conditional distributions are denoted by $\p^{x_{i+1}|x_i}$ and $\q^{x_{i+1}|x_i}$.
\end{lemma}
\paragraph{Hard instance construction.}
To provide a lower bound on $\nsamp$, it suffices to bound the expected Kl-divergence between the outcome distributions of the maximally mixed state and the mixture of ensembles in terms of $\nsamp$ and the measurement constraints. To minimize the KL-divergence, we need to pick an ensemble of hard instance states that are the least distinguishable from $\qmm$ under the measurement.

We consider the following general hard-instance construction used in recent works of tomography and certification ~\cite{acharya2025single, ADLY2025Paulinot, Liu2024role}.
\begin{definition}[Hard Instance Construction] \label{def:hard-instance}
    Let $d^{3/2} \leq \ell \leq d^2-1$ and $\{V_1,V_2, \ldots, V_{d^2-1}, V_{d^2 } = \frac{\eye_d}{d}\}$ be an orthonormal basis of $\D(\mathbb{C}^d)$. Let $z \sim \nu = Rad(\frac{1}{2})^{\otimes \ell}$, then the ensemble of states $\sigma_z$ is defined as
   \begin{align*}
       \sigma_z \eqdef \qmm + \barDelta_z, \quad \Delta_z \eqdef \frac{c\eps}{\sqrt{d}} \cdot \frac{1}{\sqrt{\ell}} \sum_{i=1}^\ell z_m V_m, \quad \barDelta_z \eqdef \Delta_z \min\left\{1, \frac{1}{2d \opnorm{\Delta_z}}\right\}.
   \end{align*} 
\end{definition}
One can think of this construction as the quantum analogue to the Paninski construction~\cite{Paninski08}. We perturb $\qmm$ along uniformly random orthogonal directions on a $\eps$-sized hypercube. $\Delta_z$ incurs normalization to ensure positive semi-definiteness of each state. We provide a useful fact regarding the normalization factor.
\begin{theorem}[{\cite[Theorem 5.2]{acharya2025single}}]
Consider the construction in~\cref{def:hard-instance} when $c \leq \frac{1}{200}$. Let $\mathcal{Z} \eqdef \{z | z \in \{-1,1\}^\ell, \Delta_z \neq \barDelta_z\}$. Then,
\begin{align*}
   \Pr[z \in \mathcal{Z}] < d\exp(-\ell^{\frac{1}{4}}).
\end{align*}
\end{theorem}
Essentially, the normalization factor is negligible as incurring the ``bad states'' happens with very low probability. 

\paragraph{Bridging the gap with average mutual information.}
 We prove a key result that reduces mixedness testing to  the problem communicating $\ell$ bits over a measurement-induced noisy channel.

\begin{lemma}[Distinguishability from Maximally Mixed State]
Given the state ensemble defined in~\cref{def:hard-instance},
    \begin{align*}
      \expectDistrOf{\q^{\out^\ns}}{\kldiv{\q^{\out_{i+1}|\out^{i}}}{\p^{\out_{i+1}|\out^{i}}}} \leq \frac{ c^2 \ln 4 \; \eps^2}{\ell} \sup_{\POVM \in \povmset} \opnorm{\POVM} \sum_{m=1}^\ell \mutualinfo{z_m}{x^i}
    \end{align*}
    for $i=1,2,\ldots,\nsamp$.
\end{lemma}
\begin{proof}
    We start by bounding the KL-divergence with the $\chi^2$-divergence to obtain a better dependence on the measurement constraints. 
    \begin{align}
        \expectDistrOf{\q^{\out^\ns}}{\kldiv{\q^{\out_{i+1}|\out^{i}}}{\p^{\out_{i+1}|\out^{i}}}} &\leq  \expectDistrOf{\q^{\out^\ns}}{\chisquare{\q^{\out_{i+1}|\out^{i}}}{\p^{\out_{i+1}|\out^{i}}}} \\
        &= \expectDistrOf{\q^{\out^\ns}}{\expectDistrOf{X \sim \p^{x_{i+1}|x^i}}{\beta_i(X)^2}}  \label{eq:chi-square},
    \end{align}
    where $\beta_i(x) = \frac{q^{x_{i+1}|x^i} (x) - p^{x_{i+1}|x^i}(X)}{p^{x_{i+1}|x^i}(x)}$. We use Born's rule to obtain the following expression for $\beta_i(x)^2$,
    \begin{align*}
        \beta_i(x)^2 &= \left(\frac{\expectDistrOf{Z|x^i}{ \Tr(M^{(i)}_x\sigma_Z) - \Tr(M^{(i)}_x \qmm)}}{\Tr\left(M^{(i)}_x \qmm\right)}\right)^2 =  \frac{\Tr\left(M^{(i)}_x \expectDistrOf{Z|x^i}{ \barDelta_Z}\right)^2}{\Tr\left(M^{(i)}_x \qmm\right)^2}\\
        &=  \frac{\dotprodH{M^{(i)}_x}{\expectDistrOf{Z|x_i}{\barDelta_Z}}^2}{\Tr\left(M^{(i)}_x \qmm\right)^2},
    \end{align*}
    where the last line used linearity of the expectation and inner product. We will now unravel the expectation over the $\beta_i(X)$'s,
    \begin{align*}
        \expectDistrOf{X \sim \p^{x_{i+1}|x^i}}{\beta_i(X)^2} &= \sum_{x \in \mathcal{X}} \frac{\dotprodH{M^{(i)}_x}{\expectDistrOf{Z|x_i}{\barDelta_Z}}^2}{\Tr\left(M^{(i)}_x \qmm\right)} = d \sum_{x \in \mathcal{X}} \frac{\dotprodH{M^{(i)}_x}{\expectDistrOf{Z|x_i}{\barDelta_Z}}^2}{\Tr\left(M^{(i)}_x\right)} \\
        &\leq d \sum_{x \in \mathcal{X}} \frac{\dotprodH{M^{(i)}_x}{\expectDistrOf{Z|x_i}{\Delta_Z}}^2}{\Tr\left(M^{(i)}_x\right)}= d \dotprodH{\Luders_{\POVM^{(i)}}(\expectDistrOf{Z|x^{i}}{\Delta_Z})}{\expectDistrOf{Z|x^{i}}{\Delta_Z}} \\
        &\leq d \sup_{\POVM \in \povmset} \opnorm{\POVM} \dotprodH{\expectDistrOf{Z|x^{i}}{\Delta_Z}}{\expectDistrOf{Z|x^{i}}{\Delta_Z}}.
    \end{align*}
    It now suffices to express the expected norm of the perturbation.
    \begin{align*}
        \dotprodH{\expectDistrOf{Z|x^{i}}{\Delta_Z}}{\expectDistrOf{Z|x^{i}}{\Delta_Z}} &= \frac{c^2 \eps^2}{\ell d}\sum_{m,l \in [\ell]} \expectDistrOf{z_m | x^{i}}{z_m} \expectDistrOf{z_l | x^{i}}{z_l} \dotprodH{V_m}{V_l} \\
        &= \frac{c^2 \eps^2}{\ell d} \sum_{m,l \in [\ell]} \expectDistrOf{z_m | x^{i}}{z_m} \expectDistrOf{z_l | x^{i}}{z_l} \delta_{ml} \\
        &= \frac{c^2 \eps^2}{\ell d} \sum_{m=1}^\ell \expectDistrOf{z_m | x^{i}}{z_m}^2.
    \end{align*}
    We invoke a useful lemma to characterize the expectation of the random variable $\expectDistrOf{z_m | x^{i}}{z_m}^2$ when $z_m$ is restricted to a binary random variable.  
    \begin{lemma}[{\cite[Lemma 6]{ACLST22iiuic}}]
    \label{lemma:MI-channel-lower}
    Let  $Z\in\{-1, 1\}^\ell$ be drawn uniformly and $Y$ be a random variable. Then for each $i\in[\ell]$,
    \[
     \expect{\expectCond{Z_i}{Y}^2} \leq \ln 4 \cdot \mutualinfo{Z_i}{Y}.
    \]
    \end{lemma}
    \noindent Substituting what we have into~\cref{eq:chi-square},
    \begin{align*}
        \expectDistrOf{\q^{\out^\ns}}{\kldiv{\q^{\out_{i+1}|\out^{i}}}{\p^{\out_{i+1}|\out^{i}}}} &\leq \frac{c^2 \eps^2}{\ell} \sup_{\POVM \in \povmset} \opnorm{\POVM} \sum_{m =1}^\ell \expectDistrOf{\q^{\out^\ns}}{\expectDistrOf{z_m | x^{i}}{z_m}^2} \\
        &\leq \frac{c^2 \ln 4 \; \eps^2}{\ell}  \sup_{\POVM \in \povmset} \opnorm{\POVM} \sum_{m =1}^\ell \mutualinfo{z_m}{x^i}
    \end{align*}
\end{proof}
    \noindent We will now characterize the average mutual information in terms of the measurement constraints to conclude our lower bound framework for adaptive single-copy state certification.
    \begin{theorem}[{\cite[Theorem 4.4]{ADLY2025Paulinot}}]
    \label{thm:avg-MI-upper}
    Let $x^i$ be the $x_1, x_2,\ldots,x_i$ marginal of the outcome distribution of performing $\POVM^{(1)} \otimes \POVM^{(2)} \otimes \ldots \otimes \POVM^{(n)}$ on the random state $\sigma_z^{\otimes n}$. Then, for all $i\in[\ns]$,
    \begin{align}
        \frac{1}{\ell} \sum_{m=1}^\ell \mutualinfo{z_m}{x^i} \leq \frac{8ic^2 \eps^2}{\ell^2} \sup_{\POVM \in \povmset} \sum_{m=1}^\ell \dotprodH{\Luders_\POVM(V_m)}{V_m} + 16ic^2\eps^2 \Pr[z \in \mathcal{Z}].
    \end{align}
    \end{theorem}

    \noindent Putting it all together, we have
    \begin{align} \label{eq:mdep-lb}
        \frac{1}{2}\le \kldiv{\q^{\out^\ns}}{\p^{\out^\ns}} \leq \frac{8 \ln 4 \; c^4 \nsamp^2 \eps^4}{\ell^2}  \sup_{\POVM \in \povmset} \sum_{m=1}^\ell \dotprodH{\Luders_\POVM(V_m)}{V_m} + 16 \ln 4 \; n^2c^4\eps^4 d \exp\{-\ell^{1/4}\}.
    \end{align}
    We can select a basis $\{V_1,V_2, \ldots ,V_\ell\}$ based on $\povmset$ to obtain a measurement dependent lower bound for adaptive state certification. Note, picking a complete orthonormal basis recovers the single copy bound $\bigOmega{\frac{\sqrt{8}^N}{\eps^2}}$ for large enough $N$.

