\section{The Upper Bound} \label{sec:ub}
We present our non-adaptive Pauli mixedness tester, which is optimal up to $poly(N)$ factors. To understand the main ideas of our protocol, we break the mixedness tester into two parts.
\begin{algorithm}[h]
\caption{Pauli Mixedness Tester}\label{alg:rand_test}
    \begin{algorithmic}[1] 
    \Require Copy access to $\sigma^{\otimes n}$, $\eps \in (0,1)$
    \Ensure{
    $\begin{cases} 
    \text{\texttt{Maximally-Mixed}} & \text{w.p. } \frac{2}{3} \quad \text{if } \sigma = \rho_{\text{mm}} \\ 
    \text{\texttt{Not Maximally-Mixed}} & \text{w.p. } \frac{2}{3} \quad \text{if } \|\sigma - \rho_{\text{mm}}\|_1 \geq \varepsilon 
    \end{cases}$} 
    \For{$i=1,2, \ldots, N$}
        \State $\delta_i \gets 100^{-(i+N)}$, $l_i \gets \max\left\{1,\lfloor\log_3 \frac{3^{i}}{9N}\rfloor\right\}$
        \State $\mathcal{B}_i \gets 3^i \cdot N \cdot 100$ i.i.d samples from $\unif[\{X,Y,Z\}^{\otimes N}]$ 
        \For{$P \in \mathcal{B}_i$}
            \State  $r_P \gets$ measurement outcome distribution of measuring $\sigma$ in Pauli basis $P$ 
            \For{$w=l_i,l_i+1, \ldots N$}
                \State $\beta^{(w)}_{i} \gets \frac{3^i}{9N 3^w}$
                \State $T_w \gets \mathtt{KrawtCheck}_{r_P}\left(k=w, \eps^2, \beta^{(w)}_{i}, \delta_i \right)$
                \If{$T_w = \mathtt{YES}$ }
                    \State \Return $\mathtt{Not\;Maximally-Mixed}$
                \EndIf
            \EndFor
        \EndFor
    \EndFor 
    \State \Return $\mathtt{Maximally-Mixed}$
    \end{algorithmic}
\end{algorithm}
\paragraph{Influence detection.} The two higher-level for-loops perform a random search on the Pauli basis $\{X,Y,Z\}^{\otimes \nqubits}$ to find a $P$ with a large Pauli influence $L_P$, where~\cref{lem:pauli_work_invest} shows such a basis can be found through Levin's work investment strategy. At a high-level, the work strategy states that either there exists a large number of Pauli measurements that have a typical influence, or there exists a sparser set of Pauli measurements with high influence. Thus, we can sample many Pauli bases to hopefully detect the highly influential Pauli measurement or sample fewer Pauli bases to detect a more average Pauli influence. The proof of this statement is provided in~\cref{sec:ub-proof}.
\begin{algorithm}[h]
\caption{KrawtCheck}\label{alg:sparse}
    \begin{algorithmic}[1] 
    \Require  Sample access to distribution $p$ that is either $(\Delta, k, \beta)$-correlated or uniform for $\Delta, \beta,\delta \in (0,1]$, $k \in [N]$.
    \Ensure{
     $\begin{cases} 
    \text{\texttt{YES}} & \text{w.p. } 1-\delta \quad \text{if } p \text{ is $(\Delta, \beta, k)$-correlated} \\
    \text{\texttt{NO}} & \text{w.p. } 1-\delta \quad \text{if } p = u 
    \end{cases}$
    }
    \State $M \gets 16 \ln{\frac{1}{\delta}}$ 
    \State $n \gets \frac{400\sqrt{2 \binom{N}{k}}}{\beta\Delta} $ \\
    \For{$i=1,2\ldots,M$}
    \State Sample $X_1, \ldots, X_n \sim p$ and $Y_1, \ldots, Y_n \sim p$ 
    \State $W_k \gets \frac{1}{n^2} \sum_{i=1}^n \sum_{j=1}^n \krawt{k}{d_{H}(X_i,Y_j)}$
    \State $T_i \gets \indic{W_i \geq \frac{\beta \Delta}{50}}$ 
    \EndFor \\
    \If{$\sum_{i=1}^M T_i \geq \frac{M}{2}$} 
    \State \Return $\mathtt{YES}$ 
    \Else 
    \State  \Return $\mathtt{NO}$
    \EndIf 
    \end{algorithmic}
\end{algorithm}
\paragraph{Detection based off weight.} Once an influential $P$ is sampled, the inner for-loop performs a weight-based check on each weight according to the influence factor $3^{w}$, which is embedded in the statistic $L_P$. We know that one of the weights must dominate $L_P$, resulting in a certain weight norm that dominates norm of the other weights by factor $\beta = \tildeOmega{3^{i-w}}$ (if the influence threshold was $3^i$). The check for the dominant weight is then performed with the \verb|KrawtCheck| subroutine, using the idea of correlation-concentrated testing shown by~\cref{thm:sparse-test} and proven in~\cref{sec:ub-proof}. Thus, the complexity of detection will scale accordingly by factor $3^{-i} \sqrt{9^w \binom{\nqubits}{w}} \cdot 3^i$, which is at most $\sqrt{10}^N$ at $w=9\nqubits/10$ (forgoing the $poly(N)$ factors that come from grouping $L_P$ by weight and union bound). We remark that $9\nqubits/10$ matches the minimum weight of the Pauli observables used for the lower bound construction.

We will now prove~\cref{thm:pauli-ub} by showing proving the correctness of~\cref{alg:rand_test} and showing that it uses $\tildeO{\frac{\sqrt{10}^\nqubits}{\eps^2}}$ copies.
\begin{proof}
We start out by showing that~\cref{alg:rand_test} uses $\tildeO{\frac{\sqrt{10}^N}{\eps^2}}$ copies. By~\cref{thm:sparse-test},
\begin{align*}
    n = \sum_{i=1}^N \bigO{3^{i} \cdot N} \sum_{w=l_i}^N \bigO{\frac{ \sqrt{ 9^w\binom{N}{w}} N^2}{3^i \Delta}} = \bigO{\frac{\sqrt{10}^N N^5}{\eps^2}} = \tildeO{\frac{\sqrt{10}^N}{\eps^2}}.
\end{align*}
    We proceed to show correctness under the null hypothesis. When $\sigma = \qmm$, the outcome distribution is uniform under any measurement, so the error probability comes from  \verb|KrawtCheck| incorrectly outputting $\mathtt{YES}$ when the given distribution is $r_P = u$. By union bound,
\begin{align*}
    \Pr_{\qmm}[T=\mathtt{Not\;Maximally-Mixed}] &\leq \sum_{i=1}^N 100 \cdot 3^i \cdot N^2 \cdot \delta_i  \leq \sum_{i=1}^N \frac{100 \cdot 3^i \cdot N^2}{100^{i+N}}  \\
    &\leq \sum_{i=1}^N 30^{-i} < \sum_{i=1}^{\infty} 30^{-i} <\frac{1}{4}.
\end{align*}
Now, we prove correctness when $\sigma \neq \qmm$. From \cref{pre:dist}, it can be seen that
\begin{align*}
L \eqdef \|\sigma-\qmm\|_2^2 = \sum_{Q \in \mathcal{Q} \setminus \{\eye_d\}} \alpha_Q^2 \geq \eps^2
\end{align*}
when $\|\sigma - \qmm\|_1 \geq \eps$. We will invoke \cref{lem:pauli_work_invest} to guarantee that a detectable basis measurement can be sampled with (reasonably) high probability. There exists $i^* \in [N]$ such that
\begin{align*}
    \Pr[L_P \geq 3^{i^*-2} L] \geq \frac{3^{-i^*}}{N}.
\end{align*}
Consider breaking up Pauli influence $L_P$ by weight
\begin{align*}
    L_P = \sum_{Q \triangleleft P} 3^{w(Q)} \alpha_Q^2 = \sum_{w=1}^N 3^{w} \sum_{S \in \binom{[N]}{w}} \alpha_{P}(S)^2 = \sum_{w=1}^N L_P^{(w)},
\end{align*}
where we define $L_P^{(w)} \eqdef 3^{w} \sum_{S \in \binom{[N]}{w}} \alpha_{P}(S)^2 = 3^{w} \|\alpha_{P}^{=w}\|_2^2$. If we take $w^* \eqdef \arg \max_{w \in [N]} L_P^{(w)}$, then
\begin{align*}
    \|\alpha_{P}^{=w^*}\|_2^2
    \geq \frac{3^{i^*-2} L}{3^{w^*} N} \geq \beta_{i^*}^{(w^*)} \eps^2, \quad
     \|\alpha_{P}^{=w^*}\|_2^2 \geq \frac{3^{i^*-2} L}{3^{w^*} N} \geq \beta_{i^*}^{(w^*)}\|\alpha_{P}\|_2^2
\end{align*}
for $L_P \geq 3^{i*-2} L$. We note that $w^* \geq l_{i^*}$. Otherwise, we obtain a contradiction $\|\alpha_{P}^{=w^*}\|_2^2 > \|\alpha_{P}\|_2^2$. Using~\cref{obs-pauli-fourier},
 \begin{align*}
     r_P(x) &= \frac{1}{2^N} + \frac{1}{2^N} \sum_{\emptyset \subset S \subseteq N} \parity{x} \alpha_{P}(S),
 \end{align*}
 we see that $r_P$ is $\left(\eps^2, w^*, \beta_{i^*}^{(w^*)}\right)$-correlated. The test could only fail if either (1) A desirable $P$ is not sampled in iteration $i^*$ or (2) \verb|KrawtCheck| returns $\mathtt{NO}$ on the outcome distribution of a desired $P$. We know that \verb|KrawtCheck| should return $\mathtt{NO}$ with probability $\leq \delta_{i^*}$ when $r_P$ is $\left(\eps^2, w^*, \beta_{i^*}^{(w^*)}\right)$-correlated. Thus, by union bound,
 \begin{align*}
     \Pr_{\sigma \neq \qmm}[T(x^\nsamp) &= \mathtt{Maximally-Mixed}]  \leq \Pr\left[\max_{P \in \mathcal{B}_{i^*}} L_P < 3^{i^* -2} L \right] + \delta_{i^*}. \\
 \end{align*}
 We notice that $Z \eqdef \sum_{P \in \mathcal{B}_{i^*}} \indic{L_P \geq 3^{i^*-2} L} \sim Bin(J, \gamma)$ where $J = 3^{i^*} \cdot N \cdot 100$ and $\gamma \geq \frac{3^{-i^*}}{N}$, resulting in 
 \begin{align*}
     \Pr\left[\max_{P \in \mathcal{B}_{i^*}} L_P < 3^{i^* -2} L \right] = (1-\gamma)^J \leq e^{-\gamma J} \leq e^{-100} < \frac{1}{8}.
 \end{align*}
 The error probability under $\sigma\neq\qmm$ is
 \begin{align*}
      \Pr_{\sigma \neq \qmm}[T(x^n) = \mathtt{Maximally-Mixed}] < \frac{1}{8} + \delta_{i^*} < \frac{1}{4}.
 \end{align*}
Thus, we have proven~\cref{thm:pauli-ub}.
\end{proof}

